<template>
  <div class="page-header q-mb-md">
    <div class="page">{{ header }}</div>
  </div>
  <q-form
    class="q-gutter-y-md rounded-borders q-pa-md bg-primary q-ma-md register-form"
    @submit="onSubmit"
  >
    <q-input
      ref="loginNameRef"
      filled
      v-model="regForm.loginName"
      label="ชื่อล็อกอิน"
      lazy-rules
      :rules="[(val) => (val && val.length > 0) || 'ใส่ชื่อผู้ใช้',
        val => (val.length > 5 && val.length <= 12) || 'ชื่อที่ใช้ลงทะเบียน ควรมีพยัญชนะ 6-12 ตัว']"
      color="white"
    >
      <template v-slot:prepend>
        <q-icon name="person_outline"/>
      </template>
    </q-input>
    <q-input
      ref="pwdRef"
      filled
      v-model="regForm.password"
      label="รหัสผ่าน"
      lazy-rules
      :type="isPwd ? 'password' : 'text'"
      :rules="[
        (val) => (val && val.length > 0) || 'ใส่รหัสผ่าน',
        (val) => (val.length > 5 && val.length <= 12) || 'ความยาวของรหัสผ่านควรอยู่ระหว่าง 6-12',
        (val) => (val && (pwdStrength == 'normal' || pwdStrength == 'strong' ) ) || 'ระดับความปลอดภัยของรหัสผ่านต้องอยู่ในเกณท์ดีเป็นอย่างน้อย'
      ]"
      color="white"
    >
      <template v-slot:prepend>
        <q-icon name="lock_open"/>
      </template>
      <template v-slot:append>
        <q-icon
          :name="isPwd ? 'visibility_off' : 'visibility'"
          class="cursor-pointer"
          @click="isPwd = !isPwd"
        />
      </template>
    </q-input>

    <div v-if="regForm.password" class="password-str-div">
      <span
        :class="{ 'weak-pwd' : pwdStrength == 'weak' ,  'normal-pwd': pwdStrength == 'normal' , 'strong-pwd' : pwdStrength == 'strong'   }">อ่อน</span>
      <span :class="{  'normal-pwd': pwdStrength == 'normal' , 'strong-pwd' : pwdStrength == 'strong'   }">ดี</span>
      <span :class="{ 'strong-pwd' : pwdStrength == 'strong'   }">รัดกุม</span>
    </div>

    <q-input
      ref="confirmPwdRef"
      filled
      :type="isCfmPwd ? 'password' : 'text'"
      v-model="regForm.confirmPwd"
      label="ยืนยันรหัสผ่าน"
      lazy-rules
      :rules="[
        (val) => (val && val.length > 0) || 'กรุณายืนยันรหัสผ่าน',
        (val) => val === regForm.password || 'รหัสผ่านไม่เหมือนกัน',
         (val) => (val.length > 5 && val.length <= 12) || 'ความยาวของรหัสผ่านควรอยู่ระหว่าง 6-12'
      ]"
      color="white"
    >
      <template v-slot:prepend>
        <q-icon name="lock_open"/>
      </template>
      <template v-slot:append>
        <q-icon
          :name="isCfmPwd ? 'visibility_off' : 'visibility'"
          class="cursor-pointer"
          @click="isCfmPwd = !isCfmPwd"
        />
      </template>
    </q-input>

    <q-input
      ref="telRef"
      filled
      v-model="regForm.telephone"
      label="เบอร์โทรศัพท์"
      lazy-rules
      :rules="[
        (val) => (val && val.length > 0) || 'กรุณายืนยันเบอร์โทรศัพท์',
        (val) => (val && val.length > 7) || 'โปรดป้อนหมายเลขโทรศัพท์มือถือที่ถูกต้อง',
      ]"
      color="white"
    >
      <template v-slot:prepend>
        <q-icon name="smartphone"/>
      </template>
    </q-input>

    <q-input
      ref="emailRef"
      type="email"
      filled
      v-model="regForm.email"
      label="อีเมลล์"
      lazy-rules
      :rules="[
        (val) => (val && val.length > 0) || 'กรุณาใส่ที่อยู่อีเมลล์',
        isValidEmail
      ]"
      color="white"
    >
      <template v-slot:prepend>
        <q-icon name="mail_outline"/>
      </template>
    </q-input>
    <q-input
      ref="verificationRef"
      filled
      type="text"
      v-model="regForm.captchaCode"
      label="รหัสยืนยัน"
      lazy-rules
      color="white"
      :rules="[
        (val) => (val && val.length > 3) || 'ใส่รหัสยืนยัน'
      ]"
    >
      <template v-slot:append>
        <img :src="verificationImg" @click="getCode()"/>
      </template>
      <template v-slot:prepend>
        <q-icon name="security"/>
      </template>
    </q-input>

    <div class="row justify-between items-center">
      <q-btn
        @click.prevent="onSubmit"
        label="ลงทะเบียนตอนนี้"
        type="submit"
        color="brand"
      />
    </div>
  </q-form>
  <div class="text-center q-mb-md">
    <router-link class="forget-pwd-tip" to="/login">
      เป็นสมาชิกอยู่แล้วหรือยัง？เข้าสู่ระบบตอนนี้
    </router-link>
  </div>
</template>

<script>
import {defineComponent, ref, reactive, onMounted, watch} from "vue";
import {api} from "boot/axios";
import {useQuasar, Platform} from "quasar";
import {useRoute, useRouter} from "vue-router";

export default defineComponent({
  name: "RegisterPage",
  setup() {
    onMounted(() => {
      getCode();
    });
    const verificationImg = ref("");
    const regForm = reactive({
      loginName: "",
      password: "",
      confirmPwd: "",
      telephone: "",
      email: "",
      captchaCode: "",
      regHost: location.hostname,
      codeId: ""
    });
    const getCode = () => {
      api
        .get("/member/verificationCode")
        .then((res) => {
          const response = res.data;
          if (response.code === 0) {
            verificationImg.value =
              "data:image/png;base64," + response.data.img;
            regForm.codeId = response.data.id;
          }
        })
        .catch((e) => {
          $q.notify({
            color: "negative",
            position: "top",
            message: e.message,
            icon: "report_problem"
          });
        });
    };
    const loginNameRef = ref();
    const pwdRef = ref();
    const confirmPwdRef = ref();
    const telRef = ref();
    const emailRef = ref();
    const verificationRef = ref();
    const $q = useQuasar();
    const pwdStrength = ref('');

    const isValidEmail = () => {
      const emailPattern =
        /^(?=[a-zA-Z0-9@._%+-]{6,254}$)[a-zA-Z0-9._%+-]{1,64}@(?:[a-zA-Z0-9-]{1,63}\.){1,8}[a-zA-Z]{2,63}$/;
      return emailPattern.test(regForm.email) || "อีเมลยังไม่มีการใช้งาน";
    };
    const router = useRouter();
    const onSubmit = () => {
      loginNameRef.value.validate();
      pwdRef.value.validate();
      confirmPwdRef.value.validate();
      telRef.value.validate();
      emailRef.value.validate();
      verificationRef.value.validate();
      $q.loading.show({
        message: "Registering"
      });
      var qs = require("qs")
      if (
        loginNameRef.value.hasError ||
        pwdRef.value.hasError ||
        confirmPwdRef.value.hasError ||
        telRef.value.hasError ||
        emailRef.value.hasError ||
        verificationRef.value.hasError
      ) {
        $q.loading.hide();
      } else {
        (regForm.regDevice = Platform.is.mobile ? "H5" : "WEB"),
          // regForm.realName = regForm.loginName
        api
          .post("/member/register", qs.stringify(regForm))
          .then((ret) => {
            const res = ret.data;
            if (res.code === 0) {
              router.push("/login");

              $q.notify({
                color: "positive",
                position: "top",
                message: "ลงทะเบียนสำเร็จ",
                icon: "check_circle_outline"
              });
            } else {
              $q.notify({
                color: "negative",
                position: "top",
                message: res.message,
                icon: "report_problem"
              });
            }
            $q.loading.hide();
          })
          .catch((error) => {
            $q.loading.hide();
            $q.notify({
              color: "negative",
              position: "top",
              message: error.message,
              icon: "report_problem"
            });
          });
        getCode();
      }
    };

    watch(() => regForm.password, () => {
      pwdStrength.value = '';

      var pwd = regForm.password;
      var result = 0;
      for (var i = 0, len = pwd.length; i < len; ++i) {
        result |= charType(pwd.charCodeAt(i));
      }

      var level = 0;
      for (var i = 0; i <= 4; i++) {
        if (result & 1) {
          level++;
        }
        result = result >>> 1;
      }

      // console.log(level);

      if (pwd.length >= 6) {
        switch (level) {
          case 1:
            pwdStrength.value = 'weak';
            break;
          case 2:
            pwdStrength.value = 'normal';
            break;
          case 3:
          case 4:
            pwdStrength.value = 'strong';
            break;
        }
      } else {
        pwdStrength.value = 'weak';
      }

      // console.log(pwdStrength.value);
    });


    return {
      header: "ลงทะเบียนบัญชี",
      regForm,
      verificationImg,
      loginNameRef,
      pwdRef,
      confirmPwdRef,
      telRef,
      emailRef,
      verificationRef,
      onSubmit,
      isValidEmail,
      isPwd: ref(true),
      isCfmPwd: ref(true),
      getCode,
      pwdStrength
    };
  }
});

function charType(num) {
  if (num >= 48 && num <= 57) {
    return 1;
  }
  if (num >= 97 && num <= 122) {
    return 2;
  }
  if (num >= 65 && num <= 90) {
    return 4;
  }
  return 8;
}
</script>
<style lang="scss">
.page-header {
  background-image: linear-gradient(to right, #de4545, #db7e42);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  font-size: 28px;
  text-align: center;
  font-family: Wave;
  padding: 10px;
  display: flex;
  gap: 20px;
  align-content: center;
  justify-content: center;
}

.verification {
  display: flex;
  padding: 10px;
}

.space-between {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.txt-center {
  text-align: center;
  padding: 0 10px;
}

.password-str-div {
  display: flex;
  align-items: center;
  margin-top: 3px;
  margin-bottom: 5px;
  justify-content: space-evenly;
  gap: 5px;
  height: 50px;

  span {
    padding: 8px 3px;
    //border: 1px solid #fff;
    border-radius: 5px;
    background: #434343;
    width: 33%;
    text-align: center;
    font-family: "Roboto", "-apple-system", "Helvetica Neue", Helvetica, Arial, sans-serif;
  }

  span.weak-pwd {
    background: var(--q-negative);
  }

  span.normal-pwd {
    background: var(--q-warning);
    color: var(--q-primary);
  }

  span.strong-pwd {
    //background: linear-gradient(to right, #de4545, #db7e42) !important;
    background:  var(--q-positive);
    font-weight: 600;
  }
}

.register-form{
  .q-field--error .q-field__bottom{
    font-size: 15px;

  }
}
</style>
